package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import java.util.*;
/** All mutations still go through the server; this screen only edits a bounded draft. */
public final class NtScreen extends Screen {
 private EditBox widthBox,heightBox,spacingBox,trimBox;private int x,y,w,selection;private boolean sides,deleteConfirm;private Button build;private List<NtTunnel> nearby=List.of();
 public NtScreen(){super(Component.literal("NT-01 Tunnel Builder"));}
 private Button button(String label,int xx,int yy,int ww,Runnable run){return addRenderableWidget(Button.builder(Component.literal(label),b->run.run()).bounds(xx,yy,ww,20).build());}
 private EditBox input(double value,int xx,int yy){var b=new EditBox(font,xx,yy,66,18,Component.literal("Tunnel setting"));b.setMaxLength(8);b.setValue(Double.toString(value));addRenderableWidget(b);return b;}
 @Override protected void init(){w=Math.min(390,width-16);x=(width-w)/2;y=Math.max(2,(height-236)/2);var s=NtClient.settings;sides=s.sides();widthBox=input(s.width(),x+90,y+24);heightBox=input(s.height(),x+w-70,y+24);spacingBox=input(s.spacing(),x+90,y+47);trimBox=input(s.trim(),x+w-70,y+47);
  button(sides?"Side nets: ON":"Side nets: OFF",x+8,y+70,w/2-12,()->{sides=!sides;apply();rebuildWidgets();});button("Apply settings",x+w/2+4,y+70,w/2-12,this::apply);
  button("< Point",x+8,y+92,75,()->NtClient.selected=Math.max(0,NtClient.selected-1));button("Point >",x+87,y+92,75,()->NtClient.selected=Math.min(NtClient.points.size()-1,NtClient.selected+1));button("Move point",x+166,y+92,90,()->{if(NtClient.selected>=0){NtClient.moving=true;onClose();}});button("Delete point",x+260,y+92,w-268,NtClient::deletePoint);
  button("Undo last point",x+8,y+114,116,NtClient::undoPoint);button("Finish route",x+128,y+114,116,()->{apply();NtClient.drawing=false;NtClient.status="Route finished. Review the preview and materials, then Build.";});button("Continue / extend",x+248,y+114,w-256,()->{apply();NtClient.drawing=true;onClose();});
  build=button("Build / update",x+8,y+136,116,()->NtClient.send(NtRequest.BUILD));button("Cancel draft",x+128,y+136,116,()->{NtClient.cancel();onClose();});button("Undo last build",x+248,y+136,w-256,()->NtClient.send(NtRequest.UNDO));
  nearby=NtClient.TUNNELS.values().stream().filter(t->minecraft.player!=null&&(t.owner().equals(minecraft.player.getUUID())||minecraft.player.hasPermissions(2))).sorted(Comparator.comparingDouble(t->t.plan().points().get(0).distanceToSqr(minecraft.player.position()))).toList();selection=Math.max(0,Math.min(selection,nearby.size()-1));button("<",x+8,y+199,26,()->{if(!nearby.isEmpty())selection=Math.floorMod(selection-1,nearby.size());});button(">",x+38,y+199,26,()->{if(!nearby.isEmpty())selection=(selection+1)%nearby.size();});button("Load selected",x+68,y+199,112,()->{if(!nearby.isEmpty()){NtClient.load(nearby.get(selection));rebuildWidgets();}});button("Remove tunnel",x+184,y+199,w-192,()->{if(NtClient.editing==null){NtClient.status="Load your tunnel first.";return;}if(!deleteConfirm){deleteConfirm=true;NtClient.status="Click Remove tunnel again to confirm deletion.";}else{NtClient.send(NtRequest.REMOVE);deleteConfirm=false;}});

 }
 private void apply(){try{NtClient.settings=new NtGeometry.Settings(Double.parseDouble(widthBox.getValue()),Double.parseDouble(heightBox.getValue()),Double.parseDouble(spacingBox.getValue()),Double.parseDouble(trimBox.getValue()),sides);NtClient.changed();}catch(IllegalArgumentException ex){NtClient.status=ex.getMessage()==null?"Enter valid numeric settings.":ex.getMessage();}}
 @Override public void tick(){if(build!=null)build.active=!NtClient.pending&&NtClient.preview!=null&&NtClient.preview.valid();}
 @Override public boolean isPauseScreen(){return false;}
 @Override public void render(GuiGraphics g,int mx,int my,float partial){renderBackground(g);drawPanel(g);super.render(g,mx,my,partial);}
 private void drawPanel(GuiGraphics g){g.fill(x,y,x+w,y+236,0xe51a2220);g.drawCenteredString(font,title,x+w/2,y+8,0xffeeeeee);g.drawString(font,"Width (clear)",x+8,y+29,0xffffff,false);g.drawString(font,"Height (clear)",x+w/2+3,y+29,0xffffff,false);g.drawString(font,"Post spacing",x+8,y+52,0xffffff,false);g.drawString(font,"Corner rounding",x+w/2+3,y+52,0xffffff,false);g.drawString(font,"Point "+(NtClient.selected+1)+" / "+NtClient.points.size()+(NtClient.pending?" | waiting for server":""),x+8,y+226,0xffdddddd,false);String saved=nearby.isEmpty()?"No owned tunnel nearby":nearby.get(selection).id().toString().substring(0,8)+" r"+nearby.get(selection).revision();g.drawString(font,"Saved: "+saved,x+8,y+183,0xffdddddd,false);var lines=font.split(Component.literal(NtClient.status),w-16);int yy=y+160;for(int i=0;i<Math.min(2,lines.size());i++)g.drawString(font,lines.get(i),x+8,yy+i*9,NtClient.preview!=null&&!NtClient.preview.valid()?0xffff7777:0xffcce3cc,false);}
}
